<?php
declare(strict_types=1);

/**
 * gestion_coaching/lib/coaching_logo_base64.php
 *
 * Logo institucional real, extraído directamente de los 3 Word
 * originales (idéntico en Formato_Retroalimentacion_Indicador.docx y
 * Formato_Compromiso_Indicador.docx — word/media/image1.png). Se
 * incrusta en base64 dentro del PDF generado, para que el documento no
 * dependa de ningún archivo externo ni de una ruta de imagen que pueda
 * romperse en el servidor.
 *
 * Devuelve el string listo para usar directo en un atributo src="" de
 * una etiqueta <img> dentro del HTML que arma mPDF.
 */
function coachingLogoInstitucionalBase64(): string
{
    return 'data:image/png;base64,';
}
